        if attempt.classification == "verified_defect" {
            let linked = record_findings
                .iter()
                .filter(|(_, attempt_id)| **attempt_id == attempt.id)
                .map(|(finding_id, _)| *finding_id)
                .collect::<BTreeSet<_>>();
