fn verify_review_record(
    root: &Utf8Path,
    review: &Review,
    record: &ReviewRecord,
    record_path: &Utf8Path,
) -> Result<()> {
    let who = &review.reviewer;
    require_eq(
        "review record model_family",
        &record.reviewer.model_family,
