 168	/// The body of `name` in `text`: from its `fn` line to the first line that is a
 169	/// bare `}` at column zero — under rustfmt only a top-level item closes there,
 170	/// so nested blocks cannot end the scan early.
 171	fn item_body<'a>(text: &'a str, name: &str) -> Option<&'a str> {
 172	    let start = text.find(&format!("fn {name}("))?;
 173	    let rest = &text[start..];
 174	    let end = rest.find("\n}\n").map_or(rest.len(), |index| index + 2);
 175	    Some(&rest[..end])
 176	}
