   1	//! L0 — the lossless Concrete Syntax Tree and the coarse structural scan.
   2	//!
   3	//! The CST preserves exact bytes, tokens, whitespace, comments, delimiters,
   4	//! attribute order, alias spelling, invalid syntax, source ranges, and
   5	//! embedded-language boundaries (v4 §9). The coarse structural scan cheaply
   6	//! identifies block boundaries and leaves unneeded regions as [`OpaqueBlock`]
   7	//! stubs so that large workspaces are never eagerly elaborated in full
   8	//! (v4 §22, §23 demand-driven parsing).
   9	//!
  10	//! Phase 1 error-tolerant coarse CST. This is intentionally not a full
  11	//! grammar: it records exact source bytes and conservative block ranges while
  12	//! deferring semantic elaboration.
  13	
  14	use liminal_id::ContentHash;
  15	use liminal_source::SourceRange;
  16	use serde::{Deserialize, Serialize};
  17	
  18	mod parser;
  19	pub use parser::{
  20	    LiminalLanguage, MAX_ERRORS, MAX_NESTING, Parse, ParseError, ParseErrorCode, SyntaxKind,
  21	    SyntaxNode, parse,
