 129	    /// A file or document root (v4 §22).
 130	    DocumentRoot,
 131	    /// A heading block (v4 §22).
 132	    Heading,
 133	    /// An ordinary paragraph-like block (v4 §22 "block boundaries").
 134	    ParagraphLike,
 135	    /// A list block (v4 §22).
 136	    List,
 137	    /// A fenced block (v4 §22).
 138	    Fence,
