 8584	fn authoritative_requirement_map()
 8585	-> BTreeMap<&'static str, (&'static str, &'static str, bool, bool)> {
 8586	    AUTHORITATIVE_REQUIREMENTS
 8587	        .iter()
 8588	        .map(|(id, kind, source, critical, stateful)| (*id, (*kind, *source, *critical, *stateful)))
 8589	        .collect()
 8590	}
 8591	
 8592	/// Evidence kinds every applicable critical requirement must carry
 8593	/// (ADR-0020 §2: "positive, negative, malformed/adversarial, basis/provenance,
 8594	/// and deterministic-replay evidence").
 8595	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
 8596	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
 8597	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
 8598	/// Requirement kinds are closed by the HAQP packet contract. An open kind
 8599	/// vocabulary lets a packet relabel a stateful requirement and evade its
 8600	/// fault/recovery evidence obligations (M17.5 P1-A04).
 8601	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
 8602	/// Current packet's stateful law is M20 D20.3. Keep the semantic coordinate
 8603	/// closed even if an attacker relabels its `kind` or drops its JSON marker.
 8604	const STATEFUL_REQUIREMENT_IDS: [&str; 1] = ["P1-R015"];
 8605	/// No single test may carry more than this share of the mutation denominator.
 8606	const MAX_KILL_SHARE: f64 = 0.25;
 8607	
 8608	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
 8609	/// covered. Every critical requirement must carry all five core evidence
 8610	/// kinds, and fault-class requirements must additionally carry injected-fault
 8611	/// and idempotent-recovery evidence.
 8612	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
 8613	    let known = CORE_EVIDENCE
 8614	        .iter()
 8615	        .chain(STATEFUL_EVIDENCE.iter())
 8616	        .copied()
 8617	        .collect::<BTreeSet<_>>();
 8618	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
 8619	    for test in &packet.tests {
 8620	        if test.evidence.is_empty() {
 8621	            anyhow::bail!("{} declares no evidence kind", test.id);
 8622	        }
 8623	        for kind in &test.evidence {
 8624	            if !known.contains(kind.as_str()) {
 8625	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
 8626	            }
 8627	        }
 8628	        for requirement in &test.requirements {
 8629	            covered
 8630	                .entry(requirement.as_str())
 8631	                .or_default()
 8632	                .extend(test.evidence.iter().map(String::as_str));
 8633	        }
 8634	    }
 8635	    for requirement in &packet.requirements {
 8636	        if !requirement.critical {
 8637	            continue;
 8638	        }
 8639	        let have = covered
 8640	            .get(requirement.id.as_str())
 8641	            .cloned()
 8642	            .unwrap_or_default();
 8643	        let mut needed = CORE_EVIDENCE.to_vec();
 8644	        if requirement.stateful || requirement.kind == "fault" {
 8645	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
 8646	        }
 8647	        let missing = needed
 8648	            .into_iter()
 8649	            .filter(|kind| !have.contains(kind))
 8650	            .collect::<Vec<_>>();
 8651	        if !missing.is_empty() {
 8652	            anyhow::bail!(
 8653	                "critical requirement {} ({}) is missing {} evidence",
 8654	                requirement.id,
 8655	                requirement.kind,
 8656	                missing.join(", ")
 8657	            );
 8658	        }
 8659	    }
 8660	    Ok(())
 8661	}
