 8663	/// Closed digest over test identity, executable name, requirement mapping, and
 8664	/// evidence kinds. Existence checks alone let a packet remap broad, unrelated
 8665	/// test names to satisfy coverage; this registry makes the authoritative
 8666	/// mapping tamper-evident (P1-A04). Recompute with the canonical NUL/US stream
 8667	/// below and update this constant in the same commit as any test inventory edit.
 8668	const TEST_REGISTRY_SHA256: &str =
 8669	    "7a29add0e81657e17786934010638abf1ea99dfee4e162921a9ef2699197d447";
 8670	
 8671	fn verify_test_registry(packet: &Packet) -> Result<()> {
 8672	    let mut canonical = String::new();
 8673	    for test in &packet.tests {
 8674	        canonical.push_str(&test.id);
 8675	        canonical.push('\0');
 8676	        canonical.push_str(&test.name);
 8677	        canonical.push('\0');
 8678	        canonical.push_str(&test.requirements.join("\x1f"));
 8679	        canonical.push('\0');
 8680	        canonical.push_str(&test.evidence.join("\x1f"));
 8681	        canonical.push('\0');
 8682	    }
 8683	    let digest = sha256_text(&canonical);
 8684	    anyhow::ensure!(
 8685	        digest == TEST_REGISTRY_SHA256,
 8686	        "test registry digest differs from closed authority: got {digest}, expected {TEST_REGISTRY_SHA256}"
 8687	    );
 8688	    Ok(())
 8689	}
