 8691	fn contains_exact_coordinate(text: &str, coordinate: &str) -> bool {
 8692	    text.match_indices(coordinate).any(|(start, _)| {
 8693	        let end = start + coordinate.len();
 8694	        !text[..start]
 8695	            .chars()
 8696	            .next_back()
 8697	            .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 8698	            && !text[end..]
 8699	                .chars()
 8700	                .next()
 8701	                .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 8702	    })
 8703	}
