 9049	/// ADR-0020 §3's shape rules for the plan: thirteen mutants per family, no
 9050	/// operator over a quarter of the denominator, and every named operator
 9051	/// present (blind pass 1 at 5fb1b57, A04).
 9052	fn verify_mutation_plan_balance(
 9053	    by_family: &BTreeMap<&str, usize>,
 9054	    by_operator: &BTreeMap<&str, usize>,
 9055	) -> Result<()> {
 9056	    const REQUIRED_OPERATORS: [&str; 13] = [
 9057	        "predicate-deletion",
 9058	        "predicate-inversion",
 9059	        "threshold-plus-one",
 9060	        "threshold-minus-one",
 9061	        "missing-enum-dispatch",
 9062	        "success-error-substitution",
 9063	        "stale-basis-acceptance",
 9064	        "wrong-holder-selection",
 9065	        "skipped-durable-transition",
 9066	        "disabled-crash-point",
 9067	        "ordering-nondeterminism",
 9068	        "oracle-short-circuit",
 9069	        "broadened-allow-list",
 9070	    ];
 9071	    for (family, count) in by_family {
 9072	        if *count != 13 {
 9073	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
 9074	        }
 9075	    }
 9076	    for (operator, count) in by_operator {
 9077	        if *count > 16 {
 9078	            anyhow::bail!("operator {operator} supplies {count} mutants; max 16");
 9079	        }
 9080	    }
 9081	    // Blind pass 1 at 5fb1b57 (A04): the tally only bounded operators that were
 9082	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
 9083	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
 9084	    // said so. The list is the ADR's, closed.
 9085	    let missing = REQUIRED_OPERATORS
 9086	        .into_iter()
 9087	        .filter(|operator| !by_operator.contains_key(operator))
 9088	        .collect::<Vec<_>>();
 9089	    anyhow::ensure!(
 9090	        missing.is_empty(),
 9091	        "the mutation plan declares no {missing:?}; ADR-0020 §3 names every operator the plan \
 9092	         must exercise, and an absent one cannot be killed or counted"
 9093	    );
 9094	    Ok(())
 9095	}
