 8414	/// A requirement coordinate is an exact anchor, not a substring assertion.
 8415	///
 8416	/// Semantic anchors such as `D18.1` must not match `D18.10`; heading anchors
 8417	/// use their complete trimmed Markdown heading (`## Exit gate`) so a generic
 8418	/// word such as `exit` cannot accidentally satisfy a gate row.
 8419	fn has_exact_coordinate_anchor(source: &str, coordinate: &str) -> bool {
 8420	    let coordinate = coordinate.trim();
 8421	    if coordinate.is_empty() {
 8422	        return false;
 8423	    }
 8424	    if coordinate.starts_with("## ") {
 8425	        return source.lines().any(|line| line.trim() == coordinate);
 8426	    }
 8427	    source.lines().any(|line| {
 8428	        line.match_indices(coordinate).any(|(offset, _)| {
 8429	            let before = line[..offset].chars().next_back();
 8430	            let after = line[offset + coordinate.len()..].chars().next();
 8431	            before.is_none_or(|ch| !coordinate_anchor_char(ch))
 8432	                && after.is_none_or(|ch| !coordinate_anchor_char(ch))
 8433	        })
 8434	    })
 8435	}
