 8721	        for test in &mutant.killing_tests {
 8722	            if !test_ids.contains(test.as_str()) {
 8723	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
 8724	            }
 8725	            *kills.entry(test.as_str()).or_default() += 1;
 8726	        }
 8727	    }
