 9082	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
 9083	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
 9084	    // said so. The list is the ADR's, closed.
 9085	    let missing = REQUIRED_OPERATORS
 9086	        .into_iter()
 9087	        .filter(|operator| !by_operator.contains_key(operator))
 9088	        .collect::<Vec<_>>();
 9089	    anyhow::ensure!(
 9090	        missing.is_empty(),
 9091	        "the mutation plan declares no {missing:?}; ADR-0020 §3 names every operator the plan \
