 9148	fn use_aliases(line: &str) -> Vec<(String, String)> {
 9149	    // Blind pass 1 at ee646f8c (A10, A11): `pub use x::y as z;` is a `use`
 9150	    // with a visibility in front, and stripping only `use ` meant the alias
 9151	    // bound nothing — in the oracle's independence scan and in the durable
 9152	    // transition census, which share this parser.
 9153	    let Some(rest) = without_visibility(line).strip_prefix("use ") else {
 9154	        return Vec::new();
 9155	    };
 9156	    // Braces are dropped rather than parsed, so a nested group
 9157	    // (`use a::{b::{c as d}};`) reads the same as a flat one: what matters is
 9158	    // the trailing `symbol as alias`, and the path before it is only used for
 9159	    // its last segment (review of d09978c).
 9160	    let flattened = rest.trim_end_matches(';').replace(['{', '}'], "");
 9161	    let items = flattened.split(',').map(str::trim).collect::<Vec<_>>();
 9162	    items
 9163	        .iter()
 9164	        .filter_map(|item| {
 9165	            let (path, alias) = item.split_once(" as ")?;
 9166	            // `rsplit` always yields at least one element.
 9167	            let symbol = path
 9168	                .rsplit("::")
 9169	                .next()
 9170	                .unwrap_or_default()
 9171	                .trim()
 9172	                .to_owned();
 9173	            let alias = alias.trim().to_owned();
 9174	            (alias != "_").then_some((symbol, alias))
 9175	        })
 9176	        .collect()
 9177	}
