  8427	    source.lines().any(|line| {
  8428	        line.match_indices(coordinate).any(|(offset, _)| {
  8429	            let before = line[..offset].chars().next_back();
  8430	            let after = line[offset + coordinate.len()..].chars().next();
  8431	            before.is_none_or(|ch| !coordinate_anchor_char(ch))
  8432	                && after.is_none_or(|ch| !coordinate_anchor_char(ch))
