  8594	/// and deterministic-replay evidence").
  8595	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
  8596	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
  8597	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
  8598	/// Requirement kinds are closed by the HAQP packet contract. An open kind
  8599	/// vocabulary lets a packet relabel a stateful requirement and evade its
  8600	/// fault/recovery evidence obligations (M17.5 P1-A04).
  8601	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
