  8608	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
  8609	/// covered. Every critical requirement must carry all five core evidence
  8610	/// kinds, and fault-class requirements must additionally carry injected-fault
  8611	/// and idempotent-recovery evidence.
  8612	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
  8613	    let known = CORE_EVIDENCE
  8614	        .iter()
  8615	        .chain(STATEFUL_EVIDENCE.iter())
  8616	        .copied()
  8617	        .collect::<BTreeSet<_>>();
  8618	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
  8619	    for test in &packet.tests {
  8620	        if test.evidence.is_empty() {
  8621	            anyhow::bail!("{} declares no evidence kind", test.id);
  8622	        }
  8623	        for kind in &test.evidence {
  8624	            if !known.contains(kind.as_str()) {
  8625	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
  8626	            }
  8627	        }
  8628	        for requirement in &test.requirements {
  8629	            covered
  8630	                .entry(requirement.as_str())
  8631	                .or_default()
  8632	                .extend(test.evidence.iter().map(String::as_str));
  8633	        }
  8634	    }
  8635	    for requirement in &packet.requirements {
  8636	        if !requirement.critical {
  8637	            continue;
  8638	        }
