  8652	            anyhow::bail!(
  8653	                "critical requirement {} ({}) is missing {} evidence",
  8654	                requirement.id,
  8655	                requirement.kind,
  8656	                missing.join(", ")
  8657	            );
  8658	        }
  8659	    }
  8660	    Ok(())
  8661	}
