  8705	/// M17.5 F-05: ADR-0020 §3 forbids mutation coverage clustering on
  8706	/// easy-to-kill paths. A 100% kill rate carried by a handful of coarse
  8707	/// end-to-end tests measures almost nothing, so cap any one test's share of
  8708	/// the denominator and require every named killer to exist.
  8709	fn verify_kill_concentration(packet: &Packet) -> Result<()> {
  8710	    let total = packet.mutants.len();
  8711	    if total == 0 {
  8712	        return Ok(());
  8713	    }
  8714	    let test_ids = packet
  8715	        .tests
  8716	        .iter()
  8717	        .map(|row| row.id.as_str())
  8718	        .collect::<BTreeSet<_>>();
  8719	    let mut kills = BTreeMap::<&str, usize>::new();
  8720	    for mutant in &packet.mutants {
  8721	        for test in &mutant.killing_tests {
  8722	            if !test_ids.contains(test.as_str()) {
  8723	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
  8724	            }
  8725	            *kills.entry(test.as_str()).or_default() += 1;
  8726	        }
  8727	    }
  8728	    for (test, count) in &kills {
  8729	        #[allow(clippy::cast_precision_loss, reason = "inventory-scale counts")]
  8730	        let share = *count as f64 / total as f64;
  8731	        // M17.5 F-30: `>` -> `>=` survives here and is EQUIVALENT within the
  8732	        // reachable domain. `share` is `count / total` over 65 declared
  8733	        // mutants, and 65/4 is not an integer, so `share == 0.25` exactly
  8734	        // cannot occur.
  8735	        if share > MAX_KILL_SHARE {
  8736	            anyhow::bail!(
  8737	                "{test} is the named killer for {count}/{total} mutants ({:.0}%), \
  8738	                 above the {:.0}% ceiling — mutation coverage is clustering on one \
  8739	                 coarse test",
  8740	                share * 100.0,
  8741	                MAX_KILL_SHARE * 100.0
  8742	            );
  8743	        }
  8744	    }
  8745	    Ok(())
  8746	}
