3017	/// The registry's commands are the project's own gates, run with the gate's
3018	/// environment and no timeout: they are what CI runs, so a hang here is a hang
3019	/// in CI, visible either way (review of `e490671`). The working directory is a
3020	/// disposable worktree at the commit the receipt names, never the live tree.
3021	fn verify_resolution_command_ran(
3022	    root: &Utf8Path,
3023	    who: &str,
3024	    evidence_text: &str,
3025	    commit: &str,
3026	) -> Result<()> {
3027	    let claimed = evidence_text
3028	        .lines()
3029	        .find_map(|line| line.trim_start().strip_prefix("verification_command:"))
3030	        .map(str::trim)
3031	        .unwrap_or_default();
3032	    let argv = RESOLUTION_COMMANDS
3033	        .iter()
3034	        .find(|(name, _)| *name == claimed)
3035	        .map(|(_, argv)| *argv)
3036	        .with_context(|| {
3037	            format!(
3038	                "{who}: resolution claims verification command {claimed:?}, which is not one the \
3039	                 gate can run; the registry is closed so a receipt cannot name a command that \
3040	                 exists only in its own text"
3041	            )
3042	        })?;
3043	    let (program, rest) = argv.split_first().context("registry command is empty")?;
3044	    // Blind pass 1 at aecb2ec7 (A12): the command ran against the working
3045	    // tree, so a receipt claiming a finding was resolved at some commit was
3046	    // answered by whether the command passes at HEAD. Reachability was
3047	    // checked and the commit then ignored. It runs in a disposable worktree
3048	    // checked out at the claimed commit now, which is what the receipt says.
3049	    let scratch = liminal_scratch::ScratchDir::new("haq-resolution-replay")?;
3050	    let worktree = scratch.path().to_owned();
3051	    let add = Command::new("git")
3052	        .current_dir(root)
3053	        .args(["worktree", "add", "--detach", "--quiet"])
3054	        .arg(&worktree)
3055	        .arg(commit)
3056	        .output()?;
3057	    anyhow::ensure!(
3058	        add.status.success(),
3059	        "{who}: resolution replay worktree add at {commit} failed: {}",
3060	        String::from_utf8_lossy(&add.stderr).trim()
3061	    );
3062	    let mut guard = WorktreeGuard::new(root, &worktree);
3063	    let status = Command::new(program)
3064	        .current_dir(&worktree)
3065	        .args(rest)
3066	        .status()
3067	        .with_context(|| format!("{who}: run resolution verification {claimed:?} at {commit}"))?;
3068	    guard.remove()?;
3069	    anyhow::ensure!(
3070	        status.success(),
3071	        "{who}: resolution claims {claimed:?} exited zero at {commit}; it exited {status}"
3072	    );
