3808	/// ADR-0020 §6's independence, checked rather than assumed (M17.5 F-27 / P1-A07).
3809	///
3810	/// The runner records `reviewer.model_family`, `reviewer.backend` and an
3811	/// identity hash precisely so independence is auditable. The qualification
3812	/// verifier never looked at any of them — this session BUILT that evidence and
3813	/// then failed to check it, which is the same mistake as trusting a status
3814	/// string. Two reviews from one family satisfy every other check in this file.
3815	fn verify_reviewer_independence(records: &[(String, ReviewRecord)]) -> Result<()> {
3816	    // M17.5 Stage 3: `< 2` -> `> 2` survives here and is EQUIVALENT, not
3817	    // untested. With fewer than two records the loop below builds sets of size
3818	    // `records.len()`, and `distinct != records.len()` is then false, so the
3819	    // function returns Ok either way. The early return states the intent —
3820	    // independence is a claim about a PAIR — and costs nothing.
3821	    if records.is_empty() {
3822	        return Ok(());
3823	    }
3824	    anyhow::ensure!(
3825	        records.len() == 2,
3826	        "blind review evidence must contain exactly two records"
3827	    );
3828	    let passes = records
3829	        .iter()
3830	        .map(|(_, record)| record.pass)
3831	        .collect::<BTreeSet<_>>();
3832	    anyhow::ensure!(
3833	        passes == BTreeSet::from([1, 2]),
3834	        "blind review records must have exactly pass ordinals 1 and 2"
3835	    );
3836	    let mut families: BTreeSet<&str> = BTreeSet::new();
3837	    let mut backends: BTreeSet<&str> = BTreeSet::new();
3838	    let mut identities: BTreeSet<&str> = BTreeSet::new();
3839	    let mut prompts: BTreeSet<&str> = BTreeSet::new();
3840	    let mut sessions: BTreeSet<&str> = BTreeSet::new();
3841	    for (who, record) in records {
3842	        if record.reviewer.model_family.trim().is_empty() {
3843	            anyhow::bail!("{who}: record names no model family");
3844	        }
3845	        if record.reviewer.identity_hash.trim().is_empty() {
3846	            anyhow::bail!("{who}: record carries no reviewer identity hash");
3847	        }
3848	        require_hex_digest(
3849	            &format!("{who} reviewer identity_hash"),
3850	            &record.reviewer.identity_hash,
3851	        )?;
3852	        require_hex_digest(
3853	            &format!("{who} sanitized_prompt_hash"),
3854	            &record.sanitized_prompt_hash,
3855	        )?;
3856	        require_hex_digest(
3857	            &format!("{who} isolated_session_hash"),
3858	            &record.isolated_session_hash,
3859	        )?;
3860	        families.insert(record.reviewer.model_family.as_str());
3861	        backends.insert(record.reviewer.backend.as_str());
3862	        identities.insert(record.reviewer.identity_hash.as_str());
3863	        prompts.insert(record.sanitized_prompt_hash.as_str());
3864	        sessions.insert(record.isolated_session_hash.as_str());
3865	    }
3866	    for (label, distinct) in [
3867	        ("model families", families.len()),
3868	        ("backends", backends.len()),
3869	        ("reviewer identities", identities.len()),
3870	        ("sanitized prompts", prompts.len()),
3871	        ("isolated sessions", sessions.len()),
3872	    ] {
3873	        if distinct != records.len() {
3874	            anyhow::bail!(
3875	                "{} reviews share {label} ({distinct} distinct across {} reviews); \
3876	                 ADR-0020 §6 requires distinct model families with isolated state",
3877	                records.len(),
