2877	/// The receipt must be the backend's own shape, and a Codex transcript must be
2878	/// retained beside the record and hash to what the receipt claims (F-49).
2879	fn verify_review_provider_receipt(record: &ReviewRecord, record_path: &Utf8Path) -> Result<()> {
2880	    let receipt = &record.provider_receipt;
2881	    require_eq(
2882	        "review provider_receipt backend",
2883	        &receipt.backend,
2884	        &record.reviewer.backend,
2885	    )?;
2886	    match receipt.backend.as_str() {
2887	        "codex" => {
2888	            anyhow::ensure!(
2889	                !receipt.session_id.trim().is_empty() && !receipt.session_file.trim().is_empty(),
2890	                "a codex receipt must name the session that answered"
2891	            );
2892	            require_hex_digest("review transcript_sha256", &receipt.transcript_sha256)?;
2893	            let transcript = record_path.with_extension("session.jsonl");
2894	            let bytes = fs::read(&transcript).with_context(|| {
2895	                format!("{transcript}: the codex transcript must be retained beside its record")
2896	            })?;
2897	            anyhow::ensure!(
2898	                bytes.len() as u64 == receipt.transcript_bytes,
2899	                "codex transcript is {} bytes, receipt claims {}",
2900	                bytes.len(),
2901	                receipt.transcript_bytes
2902	            );
2903	            require_eq(
