2909	            // authenticated and its IDENTITY was not — `session_id` and
2910	            // `session_file` only had to be non-empty, so a record could name
2911	            // one session and retain another's rollout. A rollout opens with
2912	            // its own `session_meta`, and the receipt's id ends with the UUID
2913	            // that record carries.
2914	            let first = std::str::from_utf8(&bytes)
2915	                .context("codex transcript is not UTF-8")?
2916	                .lines()
2917	                .next()
2918	                .context("codex transcript is empty")?;
2919	            let meta: serde_json::Value = serde_json::from_str(first)
2920	                .context("codex transcript's first record is not JSON")?;
2921	            anyhow::ensure!(
2922	                meta["type"] == "session_meta",
2923	                "a codex rollout opens with session_meta; this one opens with {:?}",
2924	                meta["type"]
2925	            );
2926	            let declared = meta["payload"]["session_id"]
2927	                .as_str()
2928	                .context("codex session_meta carries no session_id")?;
2929	            // Codex names a rollout `<timestamp>-<uuid>` and its `session_meta`
