2937	                "receipt names session {:?}, retained transcript is session {declared:?}",
2938	                receipt.session_id
2939	            );
2940	            require_eq(
2941	                "review provider_receipt session_file",
2942	                &receipt.session_file,
2943	                &format!("rollout-{}.jsonl", receipt.session_id),
2944	            )
2945	        }
2946	        "mimo-direct" => {
2947	            anyhow::ensure!(
2948	                !receipt.response_id.trim().is_empty(),
2949	                "a mimo receipt must carry the provider's response id"
2950	            );
2951	            anyhow::ensure!(
2952	                !receipt.provider_model.trim().is_empty(),
2953	                "a mimo receipt must carry the model the provider says answered"
2954	            );
2955	            anyhow::ensure!(
2956	                receipt.created > 0,
2957	                "a mimo receipt must carry the provider's clock"
2958	            );
2959	            for key in ["prompt_tokens", "completion_tokens", "total_tokens"] {
2960	                anyhow::ensure!(
2961	                    receipt.usage.contains_key(key),
2962	                    "a mimo receipt must carry the provider's {key}; a changed usage envelope \
2963	                     must be seen here, not discovered later through a binding that moved"
2964	                );
2965	            }
2966	            let billed = receipt
2967	                .usage
2968	                .get("total_tokens")
2969	                .and_then(serde_json::Value::as_u64)
2970	                .unwrap_or(0);
2971	            anyhow::ensure!(
2972	                billed > 0,
2973	                "a mimo receipt must carry billed usage; {:?} bills nothing",
2974	                receipt.usage
2975	            );
2976	            Ok(())
2977	        }
2978	        other => anyhow::bail!(
2979	            "review backend {other:?} produced no provider receipt; ADR-0020 §6 independence \
2980	             rests on evidence from outside this runner (F-49)"
