2878	/// retained beside the record and hash to what the receipt claims (F-49).
2879	fn verify_review_provider_receipt(record: &ReviewRecord, record_path: &Utf8Path) -> Result<()> {
2880	    let receipt = &record.provider_receipt;
2881	    require_eq(
2882	        "review provider_receipt backend",
2883	        &receipt.backend,
2884	        &record.reviewer.backend,
2885	    )?;
2886	    match receipt.backend.as_str() {
2887	        "codex" => {
2888	            anyhow::ensure!(
2889	                !receipt.session_id.trim().is_empty() && !receipt.session_file.trim().is_empty(),
2890	                "a codex receipt must name the session that answered"
2891	            );
2892	            require_hex_digest("review transcript_sha256", &receipt.transcript_sha256)?;
2893	            let transcript = record_path.with_extension("session.jsonl");
2894	            let bytes = fs::read(&transcript).with_context(|| {
2895	                format!("{transcript}: the codex transcript must be retained beside its record")
2896	            })?;
2897	            anyhow::ensure!(
2898	                bytes.len() as u64 == receipt.transcript_bytes,
2899	                "codex transcript is {} bytes, receipt claims {}",
2900	                bytes.len(),
2901	                receipt.transcript_bytes
2902	            );
2903	            require_eq(
2904	                "review transcript_sha256 (of the retained transcript)",
2905	                &format!("{:x}", Sha256::digest(&bytes)),
2906	                &receipt.transcript_sha256,
2907	            )?;
2908	            // Blind pass 1 at `aeed70f9` (A09): the transcript's bytes were
2909	            // authenticated and its IDENTITY was not — `session_id` and
2910	            // `session_file` only had to be non-empty, so a record could name
2911	            // one session and retain another's rollout. A rollout opens with
2912	            // its own `session_meta`, and the receipt's id ends with the UUID
2913	            // that record carries.
2914	            let first = std::str::from_utf8(&bytes)
2915	                .context("codex transcript is not UTF-8")?
2916	                .lines()
2917	                .next()
2918	                .context("codex transcript is empty")?;
2919	            let meta: serde_json::Value = serde_json::from_str(first)
2920	                .context("codex transcript's first record is not JSON")?;
2921	            anyhow::ensure!(
2922	                meta["type"] == "session_meta",
2923	                "a codex rollout opens with session_meta; this one opens with {:?}",
2924	                meta["type"]
2925	            );
2926	            let declared = meta["payload"]["session_id"]
2927	                .as_str()
2928	                .context("codex session_meta carries no session_id")?;
2929	            // Codex names a rollout `<timestamp>-<uuid>` and its `session_meta`
2930	            // carries the bare uuid, so the receipt's id either IS the declared
2931	            // id or ends with it after a separator. Review of `bba803d4`: a
2932	            // bare `ends_with` would also accept `xfixture` for `fixture`,
2933	            // which is a different session.
2934	            anyhow::ensure!(
2935	                receipt.session_id == declared
2936	                    || receipt.session_id.ends_with(&format!("-{declared}")),
2937	                "receipt names session {:?}, retained transcript is session {declared:?}",
2938	                receipt.session_id
2939	            );
2940	            require_eq(
2941	                "review provider_receipt session_file",
2942	                &receipt.session_file,
2943	                &format!("rollout-{}.jsonl", receipt.session_id),
2944	            )
2945	        }
2946	        "mimo-direct" => {
2947	            anyhow::ensure!(
2948	                !receipt.response_id.trim().is_empty(),
2949	                "a mimo receipt must carry the provider's response id"
2950	            );
2951	            anyhow::ensure!(
2952	                !receipt.provider_model.trim().is_empty(),
2953	                "a mimo receipt must carry the model the provider says answered"
2954	            );
2955	            anyhow::ensure!(
2956	                receipt.created > 0,
2957	                "a mimo receipt must carry the provider's clock"
2958	            );
2959	            for key in ["prompt_tokens", "completion_tokens", "total_tokens"] {
2960	                anyhow::ensure!(
2961	                    receipt.usage.contains_key(key),
2962	                    "a mimo receipt must carry the provider's {key}; a changed usage envelope \
2963	                     must be seen here, not discovered later through a binding that moved"
2964	                );
2965	            }
2966	            let billed = receipt
2967	                .usage
2968	                .get("total_tokens")
2969	                .and_then(serde_json::Value::as_u64)
2970	                .unwrap_or(0);
2971	            anyhow::ensure!(
2972	                billed > 0,
2973	                "a mimo receipt must carry billed usage; {:?} bills nothing",
2974	                receipt.usage
2975	            );
