3007	const RESOLUTION_COMMANDS: [(&str, &[&str]); 4] = [
3008	    ("just ci", &["just", "ci"]),
3009	    ("just haq-inventory", &["just", "haq-inventory"]),
3010	    ("just haq-canaries", &["just", "haq-canaries"]),
