3827	    );
3828	    let passes = records
3829	        .iter()
3830	        .map(|(_, record)| record.pass)
3831	        .collect::<BTreeSet<_>>();
3832	    anyhow::ensure!(
3833	        passes == BTreeSet::from([1, 2]),
3834	        "blind review records must have exactly pass ordinals 1 and 2"
3835	    );
3836	    let mut families: BTreeSet<&str> = BTreeSet::new();
3837	    let mut backends: BTreeSet<&str> = BTreeSet::new();
3838	    let mut identities: BTreeSet<&str> = BTreeSet::new();
3839	    let mut prompts: BTreeSet<&str> = BTreeSet::new();
3840	    let mut sessions: BTreeSet<&str> = BTreeSet::new();
3841	    for (who, record) in records {
3842	        if record.reviewer.model_family.trim().is_empty() {
3843	            anyhow::bail!("{who}: record names no model family");
3844	        }
3845	        if record.reviewer.identity_hash.trim().is_empty() {
3846	            anyhow::bail!("{who}: record carries no reviewer identity hash");
3847	        }
3848	        require_hex_digest(
3849	            &format!("{who} reviewer identity_hash"),
3850	            &record.reviewer.identity_hash,
3851	        )?;
3852	        require_hex_digest(
3853	            &format!("{who} sanitized_prompt_hash"),
3854	            &record.sanitized_prompt_hash,
3855	        )?;
3856	        require_hex_digest(
3857	            &format!("{who} isolated_session_hash"),
