2205	    // equality. This second pass binds each packet before/after boolean to the
2206	    // measured injection receipt for its closed authoritative pair.
2207	    let measured = recorded
2208	        .boundaries
2209	        .iter()
2210	        .map(|row| (row.boundary.as_str(), row.injected))
2211	        .collect::<BTreeMap<_, _>>();
