2213	        let (before, after) = crash_injection_pair(&declaration.boundary).with_context(|| {
2214	            format!(
2215	                "crash boundary {:?} lacks closed before/after pair",
2216	                declaration.boundary
2217	            )
2218	        })?;
2219	        let measured_before = measured.get(before).copied().unwrap_or(false);
2220	        let measured_after = measured.get(after).copied().unwrap_or(false);
2221	        anyhow::ensure!(
2222	            declaration.before == measured_before,
2223	            "crash boundary {} before injection claim differs from measured evidence",
2224	            declaration.boundary
2225	        );
2226	        anyhow::ensure!(
2227	            declaration.after == measured_after,
2228	            "crash boundary {} after injection claim differs from measured evidence",
2229	            declaration.boundary
2230	        );
2231	    }
2232	    Ok(())
2233	}
