2200	/// Packet booleans describe both sides of each durable transition. Bind them
2201	/// to measured evidence rows, rather than accepting packet-controlled claims
2202	/// that the runner injected both sides (P1-A12).
2203	fn verify_crash_injection_bindings(packet: &Packet, recorded: &CrashEvidence) -> Result<()> {
2204	    // verify_crash_rows already enforces exact packet/evidence boundary-set
2205	    // equality. This second pass binds each packet before/after boolean to the
2206	    // measured injection receipt for its closed authoritative pair.
2207	    let measured = recorded
2208	        .boundaries
2209	        .iter()
2210	        .map(|row| (row.boundary.as_str(), row.injected))
2211	        .collect::<BTreeMap<_, _>>();
2212	    for declaration in &packet.crash_boundaries {
2213	        let (before, after) = crash_injection_pair(&declaration.boundary).with_context(|| {
2214	            format!(
2215	                "crash boundary {:?} lacks closed before/after pair",
2216	                declaration.boundary
2217	            )
2218	        })?;
2219	        let measured_before = measured.get(before).copied().unwrap_or(false);
2220	        let measured_after = measured.get(after).copied().unwrap_or(false);
2221	        anyhow::ensure!(
2222	            declaration.before == measured_before,
2223	            "crash boundary {} before injection claim differs from measured evidence",
2224	            declaration.boundary
2225	        );
2226	        anyhow::ensure!(
2227	            declaration.after == measured_after,
2228	            "crash boundary {} after injection claim differs from measured evidence",
2229	            declaration.boundary
2230	        );
2231	    }
2232	    Ok(())
2233	}
