2238	fn crash_injection_pair(boundary: &str) -> Option<(&'static str, &'static str)> {
2239	    match boundary {
2240	        "ilrp/before_intent_commit" | "ilrp/after_intent_commit" => {
2241	            Some(("ilrp/before_intent_commit", "ilrp/after_intent_commit"))
2242	        }
2243	        "ilrp/before_external_apply" | "ilrp/after_external_apply" => {
2244	            Some(("ilrp/before_external_apply", "ilrp/after_external_apply"))
2245	        }
2246	        "ilrp/before_ack" | "ilrp/after_ack" => Some(("ilrp/before_ack", "ilrp/after_ack")),
2247	        "ilrp/before_finalize" | "ilrp/after_finalize_before_notify" => {
2248	            Some(("ilrp/before_finalize", "ilrp/after_finalize_before_notify"))
2249	        }
2250	        _ => None,
2251	    }
2252	}
